// Рассчитываем период
const today = new Date();
const yesterday = new Date(today);
yesterday.setDate(yesterday.getDate() - 1);

const periodStart = new Date('2026-01-01');
const periodEnd = yesterday;

console.log(`Период: ${periodStart.toISOString().split('T')[0]} - ${periodEnd.toISOString().split('T')[0]}`);

return {
  json: {
    period_start: periodStart.toISOString().split('T')[0],
    period_end: periodEnd.toISOString().split('T')[0],
    message: 'Period calculated successfully'
  }
};

const data = $input.first().json;
console.log('Period data:', JSON.stringify(data, null, 2));

if (data.period_start && data.period_end) {
  console.log('✅ Period calculation works!');
} else {
  console.log('❌ Period calculation failed');
}

return { json: { status: 'success', ...data } };
